from __future__ import annotations

import hashlib
from pathlib import Path
from typing import Any

from .. import __version__


# The installed supervisor package. It no longer lives inside the repository it governs, so
# the governance SHA cannot pin it; the trust anchor pins this identity instead.
KERNEL_ROOT = Path(__file__).resolve().parents[1]
GENERATED_DIRECTORIES = ("__pycache__",)
GENERATED_SUFFIXES = (".pyc", ".pyo")


def kernel_files(root: Path = KERNEL_ROOT) -> list[Path]:
    """Every file that makes up the kernel, excluding interpreter-generated bytecode."""
    result = []
    for path in sorted(root.rglob("*")):
        relative = path.relative_to(root)
        # Hidden entries are host debris (Finder's .DS_Store), never kernel content.
        if any(part in GENERATED_DIRECTORIES or part.startswith(".") for part in relative.parts):
            continue
        if path.suffix in GENERATED_SUFFIXES or path.is_dir():
            continue
        result.append(path)
    return result


def kernel_digest(root: Path = KERNEL_ROOT) -> str:
    """Content digest over the kernel's relative paths and bytes.

    Path and length are framed into the digest so moving bytes between files, or renaming a
    file, cannot produce the same value as the original tree.
    """
    digest = hashlib.sha256()
    for path in kernel_files(root):
        name = path.relative_to(root).as_posix().encode()
        content = path.read_bytes()
        digest.update(len(name).to_bytes(8, "big") + name)
        digest.update(len(content).to_bytes(8, "big") + content)
    return digest.hexdigest()


def kernel_identity(root: Path = KERNEL_ROOT) -> dict[str, Any]:
    return {"version": __version__, "digest": kernel_digest(root)}
